import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine } from '../src/invoices.js';

test('createInvoice creates a draft invoice with enriched lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2026-10-07');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 2);
  assert.deepEqual(r.value.lines[0], {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 5,
    unitPrice: 9500,
    vatRate: 21,
  });
  assert.deepEqual(r.value.lines[1], {
    sku: 'LOGO-PACK',
    name: 'Logo package',
    qty: 1,
    unitPrice: 120000,
    vatRate: 21,
  });
});

test('createInvoice returns CUSTOMER_NOT_FOUND for unknown customer', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-999',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'CUSTOMER_NOT_FOUND' }
  );
});

test('createInvoice returns DATE_INVALID for malformed dates', () => {
  const cases = ['2026-13-01', '2026-10-32', '26-10-07', '2026/10/07', '2026-10', 'not-a-date', '', '2026-10-07T12:00:00'];
  for (const date of cases) {
    assert.deepEqual(
      createInvoice({
        customerId: 'C-001',
        issueDate: date,
        lines: [{ sku: 'DEV-HOUR', qty: 1 }],
      }),
      { ok: false, error: 'DATE_INVALID' },
      `should reject: ${date}`
    );
  }
});

test('createInvoice accepts valid dates in YYYY-MM-DD format', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-01',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.equal(r.ok, true);
});

test('createInvoice returns NO_LINES for empty lines array', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [],
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice returns NO_LINES for missing lines property', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: undefined,
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice returns QTY_INVALID for invalid quantities', () => {
  const cases = [
    { qty: 0, desc: 'zero' },
    { qty: -1, desc: 'negative' },
    { qty: 1.5, desc: 'fractional' },
    { qty: '5', desc: 'string' },
    { qty: null, desc: 'null' },
    { qty: undefined, desc: 'undefined' },
  ];
  for (const { qty, desc } of cases) {
    assert.deepEqual(
      createInvoice({
        customerId: 'C-001',
        issueDate: '2026-10-07',
        lines: [{ sku: 'DEV-HOUR', qty }],
      }),
      { ok: false, error: 'QTY_INVALID' },
      `should reject qty: ${desc}`
    );
  }
});

test('createInvoice accepts positive integer quantities', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].qty, 100);
});

test('createInvoice returns UNKNOWN_SKU for unknown SKU', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'INVALID-SKU', qty: 1 }],
    }),
    { ok: false, error: 'UNKNOWN_SKU' }
  );
});

test('createInvoice handles multiple lines with different VAT rates', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
      { sku: 'PRINT-A4', qty: 100 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].vatRate, 21);
  assert.equal(r.value.lines[1].vatRate, 9);
  assert.equal(r.value.lines[2].vatRate, 0);
});

test('createInvoice does not mutate input', () => {
  const input = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  };
  const original = JSON.parse(JSON.stringify(input));
  createInvoice(input);
  assert.deepEqual(input, original);
});

test('lineTotal multiplies qty by unitPrice', () => {
  const r = lineTotal({ qty: 5, unitPrice: 9500 });
  assert.equal(r.ok, true);
  assert.equal(r.value, 47500);
});

test('lineTotal handles large amounts', () => {
  const r = lineTotal({ qty: 100, unitPrice: 120000 });
  assert.equal(r.ok, true);
  assert.equal(r.value, 12000000);
});

test('lineTotal returns INVALID_LINE for missing properties', () => {
  assert.deepEqual(lineTotal({}), { ok: false, error: 'INVALID_LINE' });
  assert.deepEqual(lineTotal({ qty: 5 }), { ok: false, error: 'INVALID_LINE' });
  assert.deepEqual(lineTotal({ unitPrice: 9500 }), { ok: false, error: 'INVALID_LINE' });
  assert.deepEqual(lineTotal(null), { ok: false, error: 'INVALID_LINE' });
  assert.deepEqual(lineTotal(undefined), { ok: false, error: 'INVALID_LINE' });
});

test('invoiceTotals calculates subtotal from all lines', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { qty: 5, unitPrice: 9500 },
      { qty: 1, unitPrice: 120000 },
    ],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 5 * 9500 + 1 * 120000);
});

test('invoiceTotals sets total equal to subtotal', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ qty: 10, unitPrice: 5000 }],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.total, r.value.subtotal);
});

test('invoiceTotals sums multiple lines correctly', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { qty: 2, unitPrice: 1000 },
      { qty: 3, unitPrice: 2000 },
      { qty: 1, unitPrice: 5000 },
    ],
  };
  const r = invoiceTotals(invoice);
  assert.equal(r.ok, true);
  assert.equal(r.value.subtotal, 2 * 1000 + 3 * 2000 + 1 * 5000);
});

test('invoiceTotals returns INVALID_INVOICE for missing lines', () => {
  assert.deepEqual(invoiceTotals(null), { ok: false, error: 'INVALID_INVOICE' });
  assert.deepEqual(invoiceTotals({}), { ok: false, error: 'INVALID_INVOICE' });
  assert.deepEqual(invoiceTotals({ lines: undefined }), { ok: false, error: 'INVALID_INVOICE' });
  assert.deepEqual(invoiceTotals({ lines: [] }), { ok: false, error: 'INVALID_INVOICE' });
});

test('invoiceTotals returns INVALID_LINE if any line is invalid', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ qty: 5, unitPrice: 9500 }, { qty: 10 }],
  };
  assert.deepEqual(invoiceTotals(invoice), { ok: false, error: 'INVALID_LINE' });
});

test('invoiceTotals on a real invoice from createInvoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(invoiceResult.ok, true);
  const totalsResult = invoiceTotals(invoiceResult.value);
  assert.equal(totalsResult.ok, true);
  assert.equal(totalsResult.value.subtotal, 5 * 9500 + 1 * 120000);
  assert.equal(totalsResult.value.total, totalsResult.value.subtotal);
});

test('addLine adds a new line to an invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(invoiceResult.ok, true);
  const invoice = invoiceResult.value;

  const r = addLine(invoice, { sku: 'LOGO-PACK', qty: 1 });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[1].sku, 'LOGO-PACK');
  assert.equal(r.value.lines[1].qty, 1);
});

test('addLine increases qty if SKU already on invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(invoiceResult.ok, true);
  const invoice = invoiceResult.value;

  const r = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].qty, 8);
});

test('addLine returns QTY_INVALID for invalid quantities', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.equal(invoiceResult.ok, true);

  const cases = [0, -1, 1.5, '5', null, undefined];
  for (const qty of cases) {
    assert.deepEqual(addLine(invoiceResult.value, { sku: 'LOGO-PACK', qty }), {
      ok: false,
      error: 'QTY_INVALID',
    });
  }
});

test('addLine returns UNKNOWN_SKU for unknown SKU', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.equal(invoiceResult.ok, true);

  assert.deepEqual(addLine(invoiceResult.value, { sku: 'INVALID-SKU', qty: 1 }), {
    ok: false,
    error: 'UNKNOWN_SKU',
  });
});

test('addLine returns NOT_DRAFT for non-draft invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.equal(invoiceResult.ok, true);
  const invoice = { ...invoiceResult.value, status: 'sent' };

  assert.deepEqual(addLine(invoice, { sku: 'LOGO-PACK', qty: 1 }), {
    ok: false,
    error: 'NOT_DRAFT',
  });
});

test('addLine returns NOT_DRAFT for null invoice', () => {
  assert.deepEqual(addLine(null, { sku: 'DEV-HOUR', qty: 1 }), {
    ok: false,
    error: 'NOT_DRAFT',
  });
});

test('addLine does not mutate original invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(invoiceResult.ok, true);
  const invoice = invoiceResult.value;
  const original = JSON.parse(JSON.stringify(invoice));

  addLine(invoice, { sku: 'LOGO-PACK', qty: 1 });
  assert.deepEqual(invoice, original);
});

test('removeLine removes a line from an invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(invoiceResult.ok, true);
  const invoice = invoiceResult.value;

  const r = removeLine(invoice, 'DEV-HOUR');
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].sku, 'LOGO-PACK');
});

test('removeLine returns LINE_NOT_FOUND for missing SKU', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.equal(invoiceResult.ok, true);

  assert.deepEqual(removeLine(invoiceResult.value, 'INVALID-SKU'), {
    ok: false,
    error: 'LINE_NOT_FOUND',
  });
});

test('removeLine returns NO_LINES if removing last line', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.equal(invoiceResult.ok, true);

  assert.deepEqual(removeLine(invoiceResult.value, 'DEV-HOUR'), {
    ok: false,
    error: 'NO_LINES',
  });
});

test('removeLine returns NOT_DRAFT for non-draft invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 1 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(invoiceResult.ok, true);
  const invoice = { ...invoiceResult.value, status: 'sent' };

  assert.deepEqual(removeLine(invoice, 'DEV-HOUR'), {
    ok: false,
    error: 'NOT_DRAFT',
  });
});

test('removeLine returns NOT_DRAFT for null invoice', () => {
  assert.deepEqual(removeLine(null, 'DEV-HOUR'), {
    ok: false,
    error: 'NOT_DRAFT',
  });
});

test('removeLine does not mutate original invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(invoiceResult.ok, true);
  const invoice = invoiceResult.value;
  const original = JSON.parse(JSON.stringify(invoice));

  removeLine(invoice, 'DEV-HOUR');
  assert.deepEqual(invoice, original);
});

test('addLine and removeLine can be chained', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(invoiceResult.ok, true);

  const add1 = addLine(invoiceResult.value, { sku: 'LOGO-PACK', qty: 1 });
  assert.equal(add1.ok, true);

  const add2 = addLine(add1.value, { sku: 'COPY-HOUR', qty: 2 });
  assert.equal(add2.ok, true);

  const remove = removeLine(add2.value, 'LOGO-PACK');
  assert.equal(remove.ok, true);
  assert.equal(remove.value.lines.length, 2);
  assert.equal(remove.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(remove.value.lines[1].sku, 'COPY-HOUR');
});

test('totals update correctly after adding a line', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(invoiceResult.ok, true);

  const totals1 = invoiceTotals(invoiceResult.value);
  assert.equal(totals1.ok, true);
  const initial = totals1.value.subtotal;

  const addResult = addLine(invoiceResult.value, { sku: 'LOGO-PACK', qty: 1 });
  const totals2 = invoiceTotals(addResult.value);
  assert.equal(totals2.ok, true);
  assert.equal(totals2.value.subtotal, initial + 120000);
});

