test('issueInvoice increments number correctly', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  assert.equal(invoiceResult.ok, true);

  const existing = ['INV-2026-0001', 'INV-2026-0002'];
  const r = issueInvoice(invoiceResult.value, existing);
  assert.equal(r.ok, true);
  assert.equal(r.value.number, 'INV-2026-0003');
});

test('issueInvoice returns NOT_DRAFT for non-draft invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.equal(invoiceResult.ok, true);
  const issued = { ...invoiceResult.value, status: 'issued' };

